/*
 * Built for Kinetic from scratch after the public preview of BoardUI's "Home Dashboard" (boardui.com/templates/dashboard).
 * No BoardUI source was used.
 */
'use client';

import { useCallback, useState } from 'react';
import type { CalendarDate } from '@internationalized/date';
import { parseDate } from '@internationalized/date';
import {
  RiAddLine,
  RiBox3Line,
  RiChatSmile2Line,
  RiGroupLine,
  RiShoppingBasketLine,
  RiTicketLine,
} from '@remixicon/react';
import { Button } from '@/components/motion/button';
import { ContributionsCard } from '@/components/motion/contributions-card';
import { EarningsChartCard } from '@/components/motion/earnings-chart-card';
import type { EarningsPeriod } from '@/components/motion/earnings-chart-card';
import { Input } from '@/components/motion/input';
import { LineChartCard } from '@/components/motion/line-chart-card';
import type { LinePeriod, LineSeries } from '@/components/motion/line-chart-card';
import { Modal, ModalBody, ModalFooter, ModalHeader } from '@/components/motion/modal';
import { RecentHiresCard } from '@/components/motion/recent-hires-card';
import type { Hire } from '@/components/motion/recent-hires-card';
import { Select, SelectItem } from '@/components/motion/select';
import { StatCards } from '@/components/motion/stat-cards';
import type { Stat } from '@/components/motion/stat-cards';
import { toast } from '@/components/motion/toast';
import {
  DashboardEmptyGrid,
  DashboardFrame,
  DashboardHeader,
  DashboardViewPlaceholder,
  DashboardWidgetMenu,
  findView,
  useWidgetToggles,
} from '@/components/motion/home-dashboard-shell';
import { HomeCustomersTable } from '@/components/motion/home-dashboard-customers';
import type { Customer } from '@/components/motion/home-dashboard-customers';
import { cx } from '@/lib/cx';

/**
 * The BoardUI home dashboard as one working page: the kit sidebar switches
 * views inside the block, the header's Filters menu shows and hides each
 * widget, Create ticket opens a form that bumps the Support tickets stat,
 * and the customers table at the foot filters, sorts, selects, edits and
 * deletes rows. Every card is a kit component fed with fixed sample data.
 */

export const HOME_TODAY: CalendarDate = parseDate('2026-11-05');

export const HOME_HIRES: Hire[] = [
  { id: 'h1', name: 'Livia Saris', role: 'Backend Engineer', startDate: parseDate('2026-11-05'), status: 'onboarding', team: 'engineering', avatarColor: 'pink' },
  { id: 'h2', name: 'Jaydon Aminoff', role: 'UI Designer', startDate: parseDate('2026-11-03'), status: 'onboarding', team: 'design', avatarColor: 'blue' },
  { id: 'h3', name: 'Maria Lubin', role: 'User Researcher', startDate: parseDate('2026-10-31'), status: 'active', team: 'research', avatarColor: 'lime' },
  { id: 'h4', name: 'Ann Press', role: 'DevOps Engineer', startDate: parseDate('2026-10-29'), status: 'active', team: 'engineering', avatarColor: 'neutral' },
  { id: 'h5', name: 'Zaire Torff', role: 'Product Designer', startDate: parseDate('2026-10-22'), status: 'active', team: 'design', avatarColor: 'blue' },
  { id: 'h6', name: 'Omar Vetrovs', role: 'Data Analyst', startDate: parseDate('2026-10-15'), status: 'active', team: 'research', avatarColor: 'neutral' },
  { id: 'h7', name: 'Talan Calzoni', role: 'Frontend Engineer', startDate: parseDate('2026-10-08'), status: 'active', team: 'engineering', avatarColor: 'lime' },
  { id: 'h8', name: 'Gretchen Septimus', role: 'Brand Designer', startDate: parseDate('2026-11-12'), status: 'pending', team: 'design', avatarColor: 'pink' },
];

const HIRE_TEAMS = [
  { value: null, label: 'Board team' },
  { value: 'engineering', label: 'Engineering' },
  { value: 'design', label: 'Design' },
  { value: 'research', label: 'Research' },
];

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const WEEKS = MONTHS.map((_, i) => `W${i + 1}`);
const YEARS = ['2019', '2020', '2021', '2022', '2023', '2024', '2025', '2026'];

const series = (labels: string[], values: number[]) => labels.map((label, i) => ({ label, value: values[i] ?? 0 }));

// The last bar is the headline; the one before it sets the change chip (7,462 vs 6,500 = +14.8%).
const EARNINGS: EarningsPeriod[] = [
  { id: 'weekly', label: 'Weekly', ticks: [0, 500, 1000, 2000], data: series(WEEKS, [980, 1420, 1880, 1210, 760, 540, 920, 1150, 1640, 1080, 1310, 1504]) },
  { id: 'monthly', label: 'Monthly', ticks: [0, 3000, 5000, 10000], data: series(MONTHS, [2700, 7400, 9600, 6900, 3600, 2200, 3800, 5000, 8100, 4400, 6500, 7462]) },
  { id: 'yearly', label: 'Yearly', ticks: [0, 25000, 50000, 75000], data: series(YEARS, [21000, 26400, 33800, 41200, 47900, 55100, 61300, 70350]) },
];

const REVENUE_SERIES: LineSeries[] = [{ key: 'revenue', label: 'Revenue', tone: 2, area: true }];
const line = (labels: string[], values: number[]) => labels.map((label, i) => ({ label, revenue: values[i] ?? 0 }));
// 18,240 vs 16,673 = +9.4%.
const REVENUE: LinePeriod[] = [
  { id: 'weekly', label: 'Weekly', data: line(WEEKS, [3100, 3420, 3380, 3860, 3720, 4010, 4260, 4110, 4390, 4520, 4300, 4704]) },
  { id: 'monthly', label: 'Monthly', data: line(MONTHS, [6200, 7900, 9800, 9100, 11800, 11200, 10400, 13100, 15400, 14600, 16673, 18240]) },
  { id: 'yearly', label: 'Yearly', data: line(YEARS, [61000, 74500, 88200, 97400, 112300, 126800, 139900, 152313]) },
];

const CONTRIBUTION_STATS = [
  { label: 'Lifetime tokens', value: '9B' },
  { label: 'Peak tokens', value: '562.7M' },
  { label: 'Longest task', value: '12h 54m' },
  { label: 'Top streak', value: '62 days' },
];

const SUPPORT_TICKETS = 708;

export type HomeWidget = 'hires' | 'earnings' | 'revenue' | 'contributions' | 'stats' | 'customers';

export const HOME_WIDGETS: readonly { id: HomeWidget; label: string }[] = [
  { id: 'hires', label: 'Recent hires' },
  { id: 'earnings', label: 'Earned so far' },
  { id: 'revenue', label: 'Revenue' },
  { id: 'contributions', label: 'Contributions' },
  { id: 'stats', label: 'Key numbers' },
  { id: 'customers', label: 'Customers' },
];

const ALL_WIDGETS: readonly HomeWidget[] = HOME_WIDGETS.map((w) => w.id);

export interface HomeDashboardProps {
  /** Nav key on screen. Controlled; pair with onViewChange. */
  view?: string;
  /** Initial nav key when uncontrolled. Default "home". */
  defaultView?: string;
  onViewChange?: (key: string) => void;
  /** First name in the greeting. Default "Mertcan". */
  userName?: string;
  /** Anchor for the hires' relative dates. Default 2026-11-05. */
  today?: CalendarDate;
  hires?: Hire[];
  /** Initial rows of the customers table. */
  customers?: readonly Customer[];
  /** Widgets shown on first render. Default all six. */
  defaultWidgets?: readonly HomeWidget[];
  className?: string;
}

// #region critical
export function HomeDashboard({
  view,
  defaultView = 'home',
  onViewChange,
  userName = 'Mertcan',
  today = HOME_TODAY,
  hires = HOME_HIRES,
  customers,
  defaultWidgets = ALL_WIDGETS,
  className,
}: HomeDashboardProps) {
  const [innerView, setInnerView] = useState(defaultView);
  const current = view ?? innerView;
  const go = useCallback(
    (key: string) => {
      if (view === undefined) setInnerView(key);
      onViewChange?.(key);
    },
    [view, onViewChange],
  );

  const widgets = useWidgetToggles(ALL_WIDGETS, defaultWidgets);
  const [ticketOpen, setTicketOpen] = useState(false);
  const [ticketsCreated, setTicketsCreated] = useState(0);
  const [team, setTeam] = useState<string | null>(null);

  const shown = widgets.isShown;

  const stats: Stat[] = [
    { icon: RiGroupLine, label: 'Customers', value: '14,592', delta: '+5.3%', deltaColor: 'lime' },
    { icon: RiBox3Line, label: 'Unit sold', value: '385', delta: '-2.1%', deltaColor: 'rose' },
    { icon: RiShoppingBasketLine, label: 'Orders', value: '1,394', delta: '0.00%', deltaColor: 'neutral' },
    {
      icon: RiChatSmile2Line,
      label: 'Support tickets',
      value: (SUPPORT_TICKETS + ticketsCreated).toLocaleString('en-US'),
      delta: '+12.8%',
      deltaColor: 'lime',
    },
  ];
  // #endregion

  const item = findView(current);
  const isHome = current === 'home';

  const actions = isHome ? (
    <>
      <DashboardWidgetMenu widgets={HOME_WIDGETS} shown={widgets.shown} onToggle={widgets.toggle} onShowAll={widgets.showAll} />
      <Button leadingIcon={RiAddLine} onClick={() => setTicketOpen(true)}>
        Create ticket
      </Button>
    </>
  ) : undefined;

  // A pair splits into columns only while both of its cards are shown.
  const topBoth = shown('hires') && shown('earnings');
  const midBoth = shown('revenue') && shown('contributions');

  return (
    <DashboardFrame view={current} onViewChange={go} label={isHome ? 'Home' : item.label} className={className}>
      <DashboardHeader
        title={isHome ? `Welcome ${userName}` : item.label}
        current={item}
        homeKey="home"
        onViewChange={go}
        actions={actions}
      />

      {isHome ? (
        <div className="mt-5 flex flex-col gap-4">
          {shown('hires') || shown('earnings') ? (
            <div className={cx('grid grid-cols-1 gap-4', topBoth && 'lg:grid-cols-[minmax(0,0.82fr)_minmax(0,1fr)]')}>
              {shown('hires') ? (
                <RecentHiresCard
                  hires={hires}
                  today={today}
                  teams={HIRE_TEAMS}
                  team={team}
                  onTeamChange={setTeam}
                  total={team === null ? 56 : (visible) => visible.length}
                  pageSize={4}
                  onViewAll={() => go('profile')}
                />
              ) : null}
              {shown('earnings') ? <EarningsChartCard periods={EARNINGS} defaultPeriod="monthly" /> : null}
            </div>
          ) : null}

          {shown('revenue') || shown('contributions') ? (
            <div className={cx('grid grid-cols-1 gap-4', midBoth && 'lg:grid-cols-2')}>
              {shown('revenue') ? <LineChartCard title="Revenue" series={REVENUE_SERIES} periods={REVENUE} defaultPeriod="monthly" /> : null}
              {shown('contributions') ? <ContributionsCard change={14.8} stats={CONTRIBUTION_STATS} /> : null}
            </div>
          ) : null}

          {shown('stats') ? <StatCards stats={stats} /> : null}

          {shown('customers') ? <HomeCustomersTable defaultCustomers={customers} /> : null}

          {widgets.shown.size === 0 ? <DashboardEmptyGrid onShowAll={widgets.showAll} /> : null}
        </div>
      ) : (
        <DashboardViewPlaceholder item={item} backLabel="Home" onBack={() => go('home')} />
      )}

      <Modal isOpen={ticketOpen} onOpenChange={setTicketOpen} size="sm">
        <TicketForm
          onCancel={() => setTicketOpen(false)}
          onCreate={(subject, priority) => {
            setTicketsCreated((n) => n + 1);
            setTicketOpen(false);
            toast('Ticket created', { status: 'success', description: `${subject} (${priority} priority)` });
          }}
        />
      </Modal>
    </DashboardFrame>
  );
}

const PRIORITIES = ['Low', 'Normal', 'Urgent'] as const;

function TicketForm({ onCancel, onCreate }: { onCancel: () => void; onCreate: (subject: string, priority: string) => void }) {
  const [subject, setSubject] = useState('');
  const [priority, setPriority] = useState<string>('Normal');
  const valid = subject.trim().length > 0;
  return (
    <form
      className="contents"
      onSubmit={(event) => {
        event.preventDefault();
        if (valid) onCreate(subject.trim(), priority.toLowerCase());
      }}
    >
      <ModalHeader icon={RiTicketLine} title="Create ticket" description="Log a request for the support team. It counts toward Support tickets." />
      <ModalBody className="flex flex-col gap-4">
        <Input label="Subject" placeholder="e.g. Refund for order #1394" value={subject} onChange={setSubject} isRequired autoFocus />
        <Select label="Priority" selectedKey={priority} onSelectionChange={(key) => key != null && setPriority(String(key))}>
          {PRIORITIES.map((p) => (
            <SelectItem key={p} id={p} textValue={p}>
              {p}
            </SelectItem>
          ))}
        </Select>
      </ModalBody>
      <ModalFooter>
        <Button type="button" variant="secondary" onClick={onCancel}>
          Cancel
        </Button>
        <Button type="submit" disabled={!valid}>
          Create ticket
        </Button>
      </ModalFooter>
    </form>
  );
}

/*
 * Built for Kinetic from scratch after the public preview of BoardUI's "Home Dashboard" (boardui.com/templates/dashboard).
 * No BoardUI source was used.
 */
'use client';

import { useCallback, useMemo, useState } from 'react';
import type { MouseEvent, ReactNode } from 'react';
import { RiArrowLeftLine, RiCheckLine, RiCustomerServiceLine, RiEqualizerLine, RiMenuLine } from '@remixicon/react';
import { DASHBOARD_NAV, DashboardSidebar } from '@/components/motion/dashboard-sidebar';
import type { DashboardNavItem } from '@/components/motion/dashboard-sidebar';
import { DashboardPageHeader } from '@/components/motion/dashboard-page-header';
import type { PageHeaderCrumb } from '@/components/motion/dashboard-page-header';
import { NotificationBellBadge } from '@/components/motion/notification-bell-badge';
import type { BellNotification } from '@/components/motion/notification-bell-badge';
import { Button, buttonStyles } from '@/components/motion/button';
import { Dropdown, DropdownDivider, DropdownItem, DropdownPopover, DropdownTrigger } from '@/components/motion/dropdown';
import { IconButton } from '@/components/motion/icon-button';
import { Toaster } from '@/components/motion/toast';
import { cx } from '@/lib/cx';

/**
 * The frame shared by the BoardUI dashboard templates (home, finance,
 * marketing): the kit sidebar, a scrolling main pane and in-block view
 * switching. The sidebar's rows are plain links, so each row gets a
 * `#view-<key>` href and one capturing click handler on the sidebar's
 * wrapper turns those links into local state changes. Keyboard Enter on a
 * link fires the same click, so this covers the keyboard too, and nothing
 * ever navigates the host page.
 */

export const VIEW_HASH = '#view-';

/** The kit nav, re-pointed at in-block views. */
export const DASHBOARD_VIEWS: readonly DashboardNavItem[] = DASHBOARD_NAV.map((item) => ({
  ...item,
  href: `${VIEW_HASH}${item.key}`,
}));

/** The secondary "Support" row has no route of its own; it opens this view. */
export const SUPPORT_VIEW: DashboardNavItem = { key: 'support', label: 'Support', icon: RiCustomerServiceLine };

export function findView(key: string, items: readonly DashboardNavItem[] = DASHBOARD_VIEWS): DashboardNavItem {
  return items.find((item) => item.key === key) ?? (key === SUPPORT_VIEW.key ? SUPPORT_VIEW : items[0] ?? SUPPORT_VIEW);
}

export const DASHBOARD_NOTIFICATIONS: readonly BellNotification[] = [
  { id: 'n1', title: 'Livia Saris joined Backend', description: 'Say hello in the team channel.', time: '2m ago', tone: 'success' },
  { id: 'n2', title: 'Payout of $7,462 is on its way', description: 'Expected in your account on Friday.', time: '1h ago', tone: 'information' },
  { id: 'n3', title: 'Delivery failed for Aspen Lubin', description: 'The carrier could not reach the address.', time: '3h ago', tone: 'error' },
  { id: 'n4', title: 'Weekly report is ready', time: 'Yesterday', tone: 'neutral' },
  { id: 'n5', title: '3 new support tickets', description: 'Two are marked urgent.', time: 'Yesterday', tone: 'information' },
];

export interface DashboardFrameProps {
  /** Nav key of the view on screen. */
  view: string;
  onViewChange: (key: string) => void;
  /** Sidebar rows. Default: the kit nav with `#view-<key>` hrefs. */
  items?: readonly DashboardNavItem[];
  /** Accessible name of the scrolling main region. */
  label?: string;
  className?: string;
  children: ReactNode;
}

// #region critical
export function DashboardFrame({
  view,
  onViewChange,
  items = DASHBOARD_VIEWS,
  label = 'Dashboard',
  className,
  children,
}: DashboardFrameProps) {
  const [drawerOpen, setDrawerOpen] = useState(false);

  // Capture phase so the decision is made before the browser follows the
  // link. DOM containment (not React's tree) keeps portalled menus out.
  const interceptNav = (event: MouseEvent<HTMLElement>) => {
    const link = (event.target as Element | null)?.closest?.('a');
    if (!link || !event.currentTarget.contains(link)) return;
    const href = link.getAttribute('href') ?? '';
    if (href.startsWith(VIEW_HASH)) {
      event.preventDefault();
      onViewChange(href.slice(VIEW_HASH.length));
      setDrawerOpen(false);
    } else if (href === '#') {
      event.preventDefault();
      if (link.getAttribute('aria-label') === SUPPORT_VIEW.label) {
        onViewChange(SUPPORT_VIEW.key);
        setDrawerOpen(false);
      }
    }
  };

  return (
    <div
      data-dashboard-view={view}
      className={cx('relative flex h-full w-full min-h-0 gap-3 overflow-hidden bg-background-full p-3 text-text-primary', className)}
    >
      <div className="hidden h-full shrink-0 lg:flex" onClickCapture={interceptNav}>
        <DashboardSidebar selected={view} items={[...items]} />
      </div>

      {drawerOpen ? (
        <div className="absolute inset-0 z-30 flex lg:hidden">
          <button
            type="button"
            aria-label="Close navigation"
            onClick={() => setDrawerOpen(false)}
            className="absolute inset-0 cursor-default bg-black/40"
          />
          <div className="relative h-full p-3" onClickCapture={interceptNav}>
            <DashboardSidebar mobile selected={view} items={[...items]} onClose={() => setDrawerOpen(false)} />
          </div>
        </div>
      ) : null}

      <main aria-label={label} className="flex min-w-0 flex-1 flex-col overflow-y-auto overscroll-contain px-1 pb-6 lg:px-2">
        <div className="mb-3 flex items-center lg:hidden">
          <IconButton icon={RiMenuLine} aria-label="Open navigation" onClick={() => setDrawerOpen(true)} />
        </div>
        {children}
      </main>

      <Toaster position="bottom-end" />
    </div>
  );
}
// #endregion

export interface DashboardHeaderProps {
  title: ReactNode;
  /** The current nav row; its label and icon close the breadcrumb. */
  current: DashboardNavItem;
  onViewChange: (key: string) => void;
  /** Where the "Board team" crumb leads. */
  homeKey: string;
  notifications?: readonly BellNotification[];
  actions?: ReactNode;
}

/** The page title row every dashboard view shares: crumbs, title, bell, actions. */
export function DashboardHeader({
  title,
  current,
  onViewChange,
  homeKey,
  notifications = DASHBOARD_NOTIFICATIONS,
  actions,
}: DashboardHeaderProps) {
  const crumbs = useMemo<PageHeaderCrumb[]>(
    () => [
      { label: 'Board team', initials: 'B', tone: 'blue', onPress: () => onViewChange(homeKey) },
      { label: 'Mertcan', initials: 'M', tone: 'neutral', onPress: () => onViewChange('profile') },
      { label: current.label, icon: current.icon },
    ],
    [current, homeKey, onViewChange],
  );
  return (
    <DashboardPageHeader
      title={title}
      breadcrumbs={crumbs}
      notifications={<NotificationBellBadge defaultNotifications={notifications} placement="bottom end" />}
      actions={actions}
      className="pt-1"
    />
  );
}

export interface DashboardViewPlaceholderProps {
  item: DashboardNavItem;
  /** Label of the page the back button returns to, e.g. "Home". */
  backLabel: string;
  onBack: () => void;
}

/** What a nav row that belongs to another template shows inside this one. */
export function DashboardViewPlaceholder({ item, backLabel, onBack }: DashboardViewPlaceholderProps) {
  const Icon = item.icon;
  return (
    <section
      aria-label={item.label}
      className="mt-5 flex min-h-[420px] flex-1 flex-col items-center justify-center gap-4 rounded-3xl bg-background-secondary-default p-8 text-center"
    >
      <span className="flex size-12 items-center justify-center rounded-2xl bg-background-inner-default text-foreground-icon-secondary shadow-card">
        <Icon aria-hidden className="size-6" />
      </span>
      <div className="flex max-w-sm flex-col gap-1">
        <h2 className="text-headline-semibold text-text-primary">{item.label}</h2>
        <p className="text-body-regular text-text-secondary">
          {item.label} is its own template in this kit. The sidebar keeps your place, so you can come straight back.
        </p>
      </div>
      <Button variant="secondary" size="small" leadingIcon={RiArrowLeftLine} onClick={onBack}>
        Back to {backLabel}
      </Button>
    </section>
  );
}

export interface DashboardWidget<Id extends string = string> {
  id: Id;
  label: string;
}

/** Which widgets of a dashboard are on screen, as a Set with toggle and reset. */
export function useWidgetToggles<Id extends string>(all: readonly Id[], initial: readonly Id[] = all) {
  const [shown, setShown] = useState<ReadonlySet<Id>>(() => new Set(initial));
  const toggle = useCallback(
    (id: Id) =>
      setShown((prev) => {
        const next = new Set(prev);
        if (next.has(id)) next.delete(id);
        else next.add(id);
        return next;
      }),
    [],
  );
  const showAll = useCallback(() => setShown(new Set(all)), [all]);
  const isShown = useCallback((id: Id) => shown.has(id), [shown]);
  return { shown, toggle, showAll, isShown };
}

const TRIGGER = cx(buttonStyles.base, buttonStyles.size.medium, buttonStyles.variant.secondary);

export interface DashboardWidgetMenuProps<Id extends string> {
  widgets: readonly DashboardWidget<Id>[];
  shown: ReadonlySet<Id>;
  onToggle: (id: Id) => void;
  onShowAll: () => void;
}

/** The header's Filters button: one pressed/unpressed row per widget, then "Show all". */
export function DashboardWidgetMenu<Id extends string>({ widgets, shown, onToggle, onShowAll }: DashboardWidgetMenuProps<Id>) {
  const [open, setOpen] = useState(false);
  const visible = widgets.filter((w) => shown.has(w.id)).length;
  return (
    <Dropdown isOpen={open} onOpenChange={setOpen}>
      <DropdownTrigger className={cx(TRIGGER, open && 'bg-background-primary-active border-border-button-active')}>
        <RiEqualizerLine aria-hidden className={buttonStyles.icon.medium} />
        <span className={buttonStyles.label.medium}>Filters</span>
        {visible < widgets.length ? (
          <span className="rounded-md bg-background-tertiary-default px-1.5 text-caption-1-medium text-text-secondary tabular-nums">
            {visible}/{widgets.length}
          </span>
        ) : null}
      </DropdownTrigger>
      <DropdownPopover aria-label="Dashboard widgets" placement="bottom end" className="w-60 p-1.5" dialogClassName="gap-0.5">
        <p className="px-2 pt-1 pb-1.5 text-caption-1-medium text-text-tertiary">Show on dashboard</p>
        {widgets.map((w) => (
          <DropdownItem key={w.id} selected={shown.has(w.id)} onSelect={() => onToggle(w.id)} className="justify-between px-2 py-1.5">
            <span className="text-body-medium">{w.label}</span>
            <RiCheckLine aria-hidden className={cx('size-[18px] text-foreground-icon-secondary', !shown.has(w.id) && 'invisible')} />
          </DropdownItem>
        ))}
        <DropdownDivider />
        <DropdownItem onSelect={onShowAll} className="px-2 py-1.5">
          <span className="text-body-medium">Show all</span>
        </DropdownItem>
      </DropdownPopover>
    </Dropdown>
  );
}

/** Shown in place of the grid when every widget is hidden. */
export function DashboardEmptyGrid({ onShowAll }: { onShowAll: () => void }) {
  return (
    <div className="flex flex-col items-center gap-3 rounded-3xl bg-background-secondary-default p-10 text-center">
      <p className="text-body-medium text-text-secondary">Every widget is hidden.</p>
      <Button variant="secondary" size="small" onClick={onShowAll}>
        Show all widgets
      </Button>
    </div>
  );
}

/*
